def options(correct,pool,key):
 p=list(dict.fromkeys(str(x) for x in pool if str(x)!=str(correct)));random.Random(key).shuffle(p);assert len(p)>=3,(correct,pool);return [str(correct)]+p[:3]
def add(i,level,family,question,correct,pool,why=None):
 Q.append(dict(id=f'mr200-{i}-{sum(q["subject"]==i for q in Q)}',subject=i,level=level,family=family,question=question,options=options(correct,pool,question+str(i)),answer=0,explanation=why or f'{names[i]}: {correct}.'))
